BEGIN;
CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,name TEXT,role TEXT NOT NULL DEFAULT 'user',created_at TIMESTAMPTZ DEFAULT now());
ALTER TABLE users ADD COLUMN IF NOT EXISTS role TEXT NOT NULL DEFAULT 'user';
CREATE TABLE IF NOT EXISTS sandbox_tenants(id UUID PRIMARY KEY,name TEXT NOT NULL,max_active_jobs INTEGER NOT NULL CHECK(max_active_jobs BETWEEN 1 AND 100),created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS sandbox_members(tenant_id UUID REFERENCES sandbox_tenants(id),user_id INTEGER NOT NULL,role TEXT NOT NULL CHECK(role IN('owner','security_engineer','security_reviewer','developer','auditor')),active BOOLEAN DEFAULT true,PRIMARY KEY(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS sandbox_idempotency(actor_id INTEGER,key TEXT,response JSONB NOT NULL,PRIMARY KEY(actor_id,key));
CREATE TABLE IF NOT EXISTS sandbox_policies(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES sandbox_tenants(id),name TEXT NOT NULL,version TEXT NOT NULL,language TEXT NOT NULL,runtime_version TEXT NOT NULL,cpu_millis INTEGER NOT NULL,memory_mb INTEGER NOT NULL,timeout_seconds INTEGER NOT NULL,network_mode TEXT NOT NULL CHECK(network_mode='deny'),max_output_bytes INTEGER NOT NULL,packages JSONB NOT NULL,state TEXT NOT NULL CHECK(state IN('pending_review','approved','rejected','retired')),created_by INTEGER NOT NULL,reviewed_by INTEGER,review_reason TEXT,reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(tenant_id,name,version));
CREATE TABLE IF NOT EXISTS sandbox_artifacts(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES sandbox_tenants(id),kind TEXT NOT NULL CHECK(kind IN('input','output')),storage_uri TEXT NOT NULL,checksum TEXT NOT NULL,size_bytes BIGINT NOT NULL CHECK(size_bytes>=0),scan_state TEXT NOT NULL CHECK(scan_state IN('pending_scan','clean','quarantined')),scan_report JSONB,scanned_by TEXT,scanned_at TIMESTAMPTZ,idempotency_key TEXT,created_by INTEGER,created_by_service TEXT,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS sandbox_jobs(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES sandbox_tenants(id),input_artifact_id BIGINT NOT NULL REFERENCES sandbox_artifacts(id),output_artifact_id BIGINT REFERENCES sandbox_artifacts(id),policy_id BIGINT NOT NULL REFERENCES sandbox_policies(id),state TEXT NOT NULL CHECK(state IN('queued','leased','awaiting_artifact_scan','completed','failed','timed_out','policy_violation','cancelled')),idempotency_key TEXT NOT NULL,requested_by INTEGER NOT NULL,worker_id TEXT,lease_token_hash TEXT,lease_expires_at TIMESTAMPTZ,exit_code INTEGER,resource_usage JSONB,failure_code TEXT,started_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,released_by INTEGER,released_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS sandbox_job_events(id BIGSERIAL PRIMARY KEY,tenant_id UUID REFERENCES sandbox_tenants(id),job_id BIGINT REFERENCES sandbox_jobs(id),event_type TEXT NOT NULL,payload JSONB NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS sandbox_audit_events(id BIGSERIAL PRIMARY KEY,tenant_id UUID REFERENCES sandbox_tenants(id),actor_id INTEGER NOT NULL,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS sandbox_jobs_queue_idx ON sandbox_jobs(state,created_at);
COMMIT;
